    <path class="t-csf" d="M${86-l/2} ${r}C${86-l/2-1} 140 ${86-l/2+2} 176 ${86-l/2+3} 194L${86+l/2-3} 194C${86+l/2-2} 176 ${86+l/2+1} 140 ${86+l/2} ${r}Z"/>
